pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;
    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }
    function testFuzz_property(uint256 depositAmt, uint256 cashOutAmt, address depositor, address withdrawer) public {
        vm.assume(depositAmt >= c.MinDeposit());
        vm.assume(cashOutAmt > 0);
        vm.assume(depositor != withdrawer);
        vm.assume(depositor != address(0) && withdrawer != address(0));
        vm.assume(depositor != address(c) && withdrawer != address(c));

        // Depositor deposits
        vm.deal(depositor, depositAmt);
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Withdrawer attempts cashOut (may have zero balance initially)
        uint256 withdrawerBal = c.balances(withdrawer);
        vm.assume(cashOutAmt <= withdrawerBal);

        vm.prank(withdrawer);
        c.CashOut(cashOutAmt);

        // Invariant: Sum of all tracked balances (depositor + withdrawer) == contract ETH balance + total cashOuts
        uint256 totalBalances = c.balances(depositor) + c.balances(withdrawer);
        uint256 contractBalance = address(c).balance;

        // In a correct system: deposited amount is in balances, withdrawn is subtracted.
        // Since no other activity, totalBalances should equal contractBalance.
        assertTrue(totalBalances == contractBalance);
    }
}

