pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 depositAmt, uint256 withdrawAmt) public {
        // Bound values to admissible domain:
        // Deposit must be at least MinDeposit (1 ether) to take effect and not overflow.
        depositAmt = bound(depositAmt, 1 ether, type(uint256).max - c.MinDeposit());
        // Withdrawal amount must be <= type(uint256).max and > 0 (make it interesting).
        withdrawAmt = bound(withdrawAmt, 1, type(uint256).max);
        // Ensure caller is not the zero address.
        vm.assume(caller != address(0));
        // Fund caller with enough ether for deposit.
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();
        // Record balance after deposit.
        uint256 balanceAfterDeposit = c.balances(caller);
        // If withdrawAmt exceeds balance, CashOut will do nothing (or revert if behavior).
        // We must restrict to valid withdrawal to observe the invariant.
        vm.assume(withdrawAmt <= balanceAfterDeposit);
        // Perform CashOut.
        vm.prank(caller);
        c.CashOut(withdrawAmt);
        // After withdrawal, the caller's balance should be exactly balanceAfterDeposit - withdrawAmt.
        uint256 balanceAfterWithdrawal = c.balances(caller);
        assertTrue(balanceAfterWithdrawal == balanceAfterDeposit - withdrawAmt);
    }
}

