pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositor != address(this));
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(depositor);
        require(balanceBefore == depositAmount, "setup: deposit not recorded");

        vm.prank(depositor);
        bool ok = false;
        try c.CashOut(withdrawAmount) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = c.balances(depositor);
        if (ok) {
            assertTrue(balanceAfter == depositAmount - withdrawAmount);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address sender, uint amount) public {
        require(amount >= c.MinDeposit());
        uint balBefore = c.balances(sender);
        c.Deposit{value: amount}();
        uint balAfter = c.balances(sender);
        assert(balAfter > balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am, uint _depAmt) public payable {
        require(address(this).balance >= _am);
        c.CashOut{value: _am}(_am);
        bool reverted; try c.Deposit{value: _depAmt}(_depAmt) { reverted = false; } catch { reverted = true; }
        assert(!reverted || c.balances(address(this)) == 0);
    }
    receive() external payable {}
}
